import{_ as e,o as a,c as r,an as n}from"./chunks/framework.DL3WMPYA.js";const u=JSON.parse('{"title":"Validation matrix","description":"","frontmatter":{},"headers":[],"relativePath":"users/benchmarks/validation-matrix.md","filePath":"users/benchmarks/validation-matrix.md","lastUpdated":null}'),o={name:"users/benchmarks/validation-matrix.md"};function i(l,t,s,d,c,g){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="Validation-matrix" tabindex="-1">Validation matrix <a class="header-anchor" href="#Validation-matrix" aria-label="Permalink to &quot;Validation matrix {#Validation-matrix}&quot;">​</a></h1><p>The single summary of where each public Kraken module stands against an external reference. Every numeric cell is the headline metric of the linked benchmark page — no value is reproduced here that is not on one of those pages. Each row gives the <strong>published/analytical reference</strong>, an <strong>independent other-solver comparison</strong> where one exists, and the <strong>tolerance met</strong> against the mandate §3 acceptance bar.</p><p>Where RheoTool covers a case it is the literal reference solver; where it does not, §3&#39;s escape clause anchors the row to the canonical published data set (Ghia 1982 for the cavity, de Vahl Davis 1983 for thermal, Clift et al. 1978 for sphere drag), each with an independent OpenFOAM cross-check where available.</p><h2 id="Matrix" tabindex="-1">Matrix <a class="header-anchor" href="#Matrix" aria-label="Permalink to &quot;Matrix {#Matrix}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Module</th><th style="text-align:right;">Analytical / published reference</th><th style="text-align:right;">Other-solver comparison</th><th style="text-align:right;">Tolerance target (§3)</th><th style="text-align:right;">Result actually met</th><th style="text-align:right;">Artifact</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Newtonian — lid-driven cavity</strong> (D2Q9 BGK)</td><td style="text-align:right;">Ghia, Ghia &amp; Shin (1982), centreline <code>u</code>/<code>v</code></td><td style="text-align:right;">OpenFOAM <code>icoFoam</code> (FVM); independently clears &lt; 1 % vs Ghia (0.49 / 0.23 / 0.46 %)</td><td style="text-align:right;">rel-L2 &lt; 1 % on u-centreline (strict); ≤ 5 % local field</td><td style="text-align:right;"><strong>PASS</strong> — rel-L2 <strong>0.47 % / 0.41 % / 1.05 %</strong> at Re = 100 / 400 / 1000 (Re = 1000 marginal, abs-RMS 0.43 %)</td><td style="text-align:right;"><a href="./cartesian-cavity">Cartesian cavity</a>; literal both-solver bundle <code>benchmarks/results/rheotool_compare/newtonian/</code> (<code>.krk</code> + CSVs + <code>plot.py</code> + figure + README)</td></tr><tr><td style="text-align:right;"><strong>Thermal — natural convection</strong> (double-distribution D2Q9)</td><td style="text-align:right;">de Vahl Davis (1983), <code>Nu</code> at Pr = 0.71</td><td style="text-align:right;">OpenFOAM <code>buoyantBoussinesqSimpleFoam</code> (FVM SIMPLE); corroborates dVD at Ra = 10³ (−0.56 %) and 10⁵ (−0.60 %)</td><td style="text-align:right;">&lt; 1 % on Nu; &lt; 2 % on velocity extrema</td><td style="text-align:right;"><strong>PASS</strong> — Nu err <strong>+0.79 % / +0.93 % / +0.79 %</strong> at Ra = 10³ / 10⁴ / 10⁵; velocity extrema all &lt; 1 %</td><td style="text-align:right;"><a href="./thermal-natural-convection">Thermal natural convection</a>; reproducible bundle (<code>.krk</code> + CSV + plot script) forthcoming</td></tr><tr><td style="text-align:right;"><strong>Thermal — natural convection, generalised Newtonian</strong> (double-distribution D2Q9, power law, half-way thermal walls)</td><td style="text-align:right;">Newtonian limit: de Vahl Davis (1983), hot-wall Nu₀ = 1.117 at Ra = 10³ (his cavity average is 1.118; Kraken computes the hot-wall mean). Power law: Turan et al. (2011), Nu read from their figures, Pr = 10</td><td style="text-align:right;">Newtonian Kraken driver (n = 1)</td><td style="text-align:right;">n = 1 within 1e-6 of the Newtonian driver; &lt; 0.5 % vs de Vahl Davis at N = 64; &lt; 1 % vs Turan et al. at Ra = 10⁴, n = 0.6 (reference uncertainty); Ra = 10³: regression gate 0.1 % on Kraken&#39;s value</td><td style="text-align:right;"><strong>2D, validated on CPU (N ≤ 96) and on one A100 (CUDA Float64, N = 64/128/256)</strong> — n = 1 gap 4.0e-16; Nu = 1.1185 vs 1.117 (+0.13 %) at N = 64, Ra = 10³; Turan, Ra = 10⁴: n = 0.6 and 1.0 within 0.6 % at every N on GPU (n = 0.6 on CPU 5.393 vs 5.40, −0.13 %, N = 32/48 extrapolated); Ra = 10³, n = 1.8 within 0.13 %; Ra = 10³, n = 1.0: 1.12 vs 1.14 (−1.7 % to −1.9 %, paper value read to ±0.02); Ra = 10³, n = 0.6: 1.99 vs 2.07 (−3.8 %, grid-converged, same on CPU, gap documented and not explained); Ra = 10⁴, n = 1.8 not converged, not a validated point; GPU and CPU agree at N = 64 to 2e-5 in Nu</td><td style="text-align:right;"><a href="./gnf-natural-convection">GNF natural convection</a>; test <code>test/test_natconv_gnf.jl</code>; GPU results in <code>benchmarks/validation/natconv_gnf/results/</code>, code kept by tag <code>archive/gnf-thermal-turan-gpu</code></td></tr><tr><td style="text-align:right;"><strong>Geometry / STL — 3D sphere drag</strong> (D3Q19 + LI-BB cut-link)</td><td style="text-align:right;">Clift, Grace &amp; Weber (1978), free-stream <code>C_d ≈ 2.61</code> at Re = 20</td><td style="text-align:right;">none (no RheoTool unbounded-sphere case); blockage extrapolation <code>D/W → 0</code> is the internal cross-check</td><td style="text-align:right;">≤ 5 % local; resolution-limited geometry gate</td><td style="text-align:right;"><strong>+8.9 %</strong> — extrapolated free-stream <code>C_d ≈ 2.84</code> vs Clift 2.61 (quadratic LSQ, R² = 0.9998); residual is finite lattice resolution</td><td style="text-align:right;"><a href="./sphere-drag-3d">Sphere drag 3D</a>; CSV <code>bench/geometry_stl/sphere_drag_conv*.csv</code></td></tr><tr><td style="text-align:right;"><strong>Grid refinement (patch and conservative AMR)</strong></td><td style="text-align:right;">not applicable</td><td style="text-align:right;">not applicable</td><td style="text-align:right;">not applicable</td><td style="text-align:right;"><strong>UNDER DEVELOPMENT, NOT VALIDATED</strong> — not part of the supported feature set. See <a href="./../../theory/10_limitations">Limitations</a>.</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><strong>Non-Newtonian — 3D generalised-Newtonian channel</strong> (D3Q19 TRT + LI-BB + Guo)</td><td style="text-align:right;">exact planar-channel solution from the stress balance, independent of the solver (Carreau, power law n = 0.7 and 1.5)</td><td style="text-align:right;">none</td><td style="text-align:right;">observed order ≥ 1.8 on each resolution pair</td><td style="text-align:right;"><strong>PASS</strong> — CPU Float64, N = 16 → 32 → 64: order <strong>2.000 / 2.000</strong> (Carreau, wall fraction 0.5), <strong>1.990 / 1.995</strong> (Carreau, 0.3), <strong>2.000 / 2.000</strong> (power law n = 0.7), <strong>1.932 / 1.950</strong> (n = 1.5). One A100 Float64 sweep, N = 32 → 256: orders <strong>1.950 to 2.001</strong> (power law n = 0.7 only to N = 128); Float32 run-through only. Isothermal, Julia API only (no <code>.krk</code> route)</td><td style="text-align:right;"><a href="./gnf3d-channel-convergence">3D GNF channel</a>; <code>test/analytical/gnf3d_channel_order.jl</code></td></tr><tr><td style="text-align:right;"><strong>Viscoelastic — Oldroyd-B cylinder</strong> (TRT-LBM, interpolated bounce-back cylinder wall)</td><td style="text-align:right;">none published at this confinement (Oldroyd-B <code>C_d</code> is solver-dependent)</td><td style="text-align:right;">RheoTool <code>rheoFoam</code> fine-mesh (<code>Cylinder/Oldroyd-BLog</code>), log-conformation</td><td style="text-align:right;">&lt; 1 % on <code>C_d</code> at Wi ≤ 1, R = 50, Re = 1</td><td style="text-align:right;"><strong>PASS</strong> — <code>C_d</code> within <strong>−0.37 % / −0.66 % / −0.75 %</strong> of rheoFoam at Wi = 0.1 / 0.5 / 1.0, β = 0.59 (diffusive scaling τ = 0.95, interpolated bounce-back cylinder wall; re-measured 2026-10-14 after the #67 forcing fix); validated only for Wi ≤ 1</td><td style="text-align:right;"><a href="./../tutorials/viscoelastic-cylinder">Viscoelastic cylinder</a></td></tr><tr><td style="text-align:right;"><strong>GPU — single-GPU efficiency</strong> (BGK D2Q9, CUDA F64)</td><td style="text-align:right;">memory-bandwidth roofline (A100-40GB, 1.555 TB/s, 144 B per D2Q9 F64 update ⇒ 10 799 MLUPS ceiling)</td><td style="text-align:right;">Palabos single-GPU F64 D3Q19 TRT (4656 MLUPS, published)</td><td style="text-align:right;">≥ 0.5 of roofline</td><td style="text-align:right;"><strong>BELOW GATE</strong> — <strong>3461 MLUPS</strong> at N = 2048 ⇒ <strong>0.32</strong> of the A100-40GB roofline (0.24 of the 80 GB ceiling); 0.74 of the Palabos number, which is D3Q19 and not like-for-like</td><td style="text-align:right;"><a href="./gpu-certification">GPU certification</a>; CSV <code>benchmarks/results/certification_a100.csv</code></td></tr><tr><td style="text-align:right;"><strong>GNF steady adjoint — Carreau–Yasuda gradient</strong> (D2Q9, 32×16 periodic obstacle channel, discrete adjoint without Enzyme)</td><td style="text-align:right;">none (the check is internal)</td><td style="text-align:right;">central finite differences of the objective; on CPU also the transposed product against Enzyme reverse mode</td><td style="text-align:right;">adjoint-vs-FD gate 2.1e-2 to 6.2e-2 (absolute, loose); CPU/GPU operator parity ≤ 1e-14 relative</td><td style="text-align:right;"><strong>PASS</strong> — one A100 (Float64): gradient vs FD <strong>9.4e-10 / 3.7e-11 / 7.1e-08 / 2.0e-09</strong> (absolute, four parameters); device vs CPU products 1.2e-16 / 8.7e-17 relative; CPU vs Enzyme 3.6e-16</td><td style="text-align:right;"><a href="./gnf-adjoint-gradient">GNF adjoint gradient</a>; CSV and log <code>benchmarks/validation/gnf_adjoint/results/</code></td></tr></tbody></table><h2 id="Notes" tabindex="-1">Notes <a class="header-anchor" href="#Notes" aria-label="Permalink to &quot;Notes {#Notes}&quot;">​</a></h2><ul><li><p><strong>Follow the artifact link</strong> for the full error-norm tables, methodology, mesh/backend details and caveats — the matrix carries only the headline metric.</p></li><li><p><strong>3D rows carry larger residuals</strong> and are documented as resolution-limited on their pages (sphere drag +8.9 %). 3D natural convection is wired (<code>natural_convection_3d</code> preset) but only smoke-validated; a quantitative 3D thermal benchmark is a future item. The 2D rows are the strict acceptance gates.</p></li><li><p><strong>Grid refinement is not part of the validated surface.</strong> Grid refinement (patch and conservative AMR) is under development and not validated; it is not part of the supported feature set. The conservative-tree AMR drag coefficient is off by a factor 1.06 to 5.6 against the reference, and patch-refined thermal walls give Nu 1.26 to 1.30 in pure conduction instead of 1.0 (issue #98). See <a href="./../../theory/10_limitations">Limitations</a>.</p></li><li><p><strong>Literal reference-solver backfill.</strong> The Newtonian cavity row ships a complete <code>benchmarks/results/rheotool_compare/newtonian/</code> bundle (both-solver CSVs, per-Re error norms, the <code>.krk</code>, and a self-contained <code>plot.py</code>). The thermal and viscoelastic literal bundles are the next legs of the same backfill.</p></li></ul>',7)])])}const p=e(o,[["render",i]]);export{u as __pageData,p as default};
